    const pending = app?.globalData?.pendingThemeId;
    if (pending) {
      app.globalData.pendingThemeId = '';
      this.switchToTheme(pending);
    }
  },

  onUnload() {
    this.clearTransitionTimers();
  },

  onPageScroll({ scrollTop }) {
    const panel = this.data.themePanels[this.data.activeIndex];
    if (!panel) {
      return;
    }
    this.applyPanelUpdates(panel.themeId, { scrollTop });
  },

  async initializeThemePanels(initialThemeId) {
    try {
      const response = await api.listThemes();
      const themes = Array.isArray(response?.themes) ? response.themes : [];
      const panels = themes.map((theme) => createPanelState(theme.themeId, theme.title));
      let activeIndex = panels.findIndex((item) => item.themeId === initialThemeId);
      if (activeIndex === -1) {
        panels.push(createPanelState(initialThemeId));
        activeIndex = panels.length - 1;
      }

      const panelIndexMap = {};
      panels.forEach((panel, index) => {
        panelIndexMap[panel.themeId] = index;
      });
      this.panelIndexMap = panelIndexMap;

      this.setData({ themePanels: panels, activeIndex });
      this.ensurePanelLoaded(panels[activeIndex]?.themeId);
      this.restorePanelScroll(panels[activeIndex]?.scrollTop || 0);
    } catch (error) {
      console.warn('Failed to initialize theme list', error);
      wx.showToast({ title: '加载主题失败', icon: 'none' });
